        uniffiCallStatus in
    uniffi_cf_ffi_fn_constructor_cofferapp_new(uniffiCallStatus
    )
}
    self.init(unsafeFromHandle: handle)
}

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_cf_ffi_fn_free_cofferapp(handle, $0) }
    }

    

    
