#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCofferApp: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CofferApp

    public static func lift(_ handle: UInt64) throws -> CofferApp {
        return CofferApp(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CofferApp) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CofferApp {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CofferApp, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCofferApp_lift(_ handle: UInt64) throws -> CofferApp {
    return try FfiConverterTypeCofferApp.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCofferApp_lower(_ value: CofferApp) -> UInt64 {
    return FfiConverterTypeCofferApp.lower(value)
}






/**
 * 解锁会话门面（`cf_session::VaultSession` 的 UniFFI Object 包装）。
 */
public protocol VaultSessionProtocol: AnyObject, Sendable {
    
    /**
     * 添加附件（FR-9.1）：`filename` 为 UTF-8 明文，`content` 为明文
     * 内容（≤ 100 MiB，超限 → 1012）。只校验条目存在（1011），不限制
     * 条目状态（docs/15 §3.1.2 边界声明）；同文件名不判重。锁定 → 1001。
     */
    func addAttachment(itemId: String, filename: String, content: Data) throws  -> FfiAttachmentMeta
    
    /**
     * 超时则锁定；返回是否执行了锁定（Swift 定时器驱动）。
     */
    func autoLockIfExpired(nowSecs: Int64)  -> Bool
    
    /**
     * 当前暴力退避门禁剩余秒数（FR-12.5；`0` = 无退避）。
     *
     * 同步只读旁路通道：门禁期内 `unlock` / `enable_biometric` /
     * `change_password` 一律返回 1002（维持 FR-1.4 不可区分性），UI 的
     * 倒计时显示只经本方法获取等待时间。与内核语义一致：内存级计数，
     * 进程重启清零（设计裁决的接受限制）。
     */
    func backoffRemainingSecs()  -> UInt64
    
    /**
     * 修改主密码（FR-1.8，docs/09 §3.2 D-2：只重封装 header 的 DEK，
     * 不重加密全库；bio 封装不受影响）。
     *
     * 门禁：需解锁态（锁定 → 1001）。流程：新密码 zxcvbn 门禁
     * （< 3 → 1010，先于任何文件操作）→ 旧密码重验证（错 → 1002，
     * header 未动）→ 新盐 + 新 KEK → 重封装 → `write_header` 原子重写。
     * 任何失败磁盘 header 保持原样，旧密码仍可解锁。
     *
     * `new_kdf` 可选传入新 Argon2id 档位顺带升级（越界 → 5002）；
     * `None` 沿用当前 header.kdf 参数。
     */
    func changePassword(oldPassword: String, newPassword: String, newKdf: FfiKdfParams?) throws 
    
    /**
     * 当前剪贴板自动清除时间（秒）；`0` 表示从不清除。
     */
    func clipboardClearSecs()  -> Int64
    
    /**
     * 复制本会话条目到目标会话所在库（FR-2.10），返回目标库新条目
     * uuid（UUIDv7 文本）。复制载荷含 TOTP / 标签 / 附件（附件文件落
     * **目标库**目录）。
     *
     * 锁不双持由内核承担（FFI 层零锁逻辑）：`dst` 须来自同一
     * [`CofferApp`] 注册表（UI 只能经 `list_vaults` + `open_vault`
     * 获得，结构上满足）。错误：src 或 dst 锁定 → 1001；src 条目
     * 不存在 → 1011；校验失败 → 5002（目标库零写入）。同库复制内核
     * 允许（产生副本），UI 层禁止选择当前库。
     */
    func copyItem(itemId: String, dst: VaultSession) throws  -> String
    
    /**
     * 创建条目，返回新条目 ID（UUIDv7 文本）。
     */
    func createItem(draft: FfiItemDraft) throws  -> String
    
    /**
     * 删除条目：`hard = false` 进回收站，`hard = true` 级联硬删。
     */
    func deleteItem(itemId: String, hard: Bool) throws 
    
    /**
     * 本地诊断摘要（FR-14.4，docs/22 §3.4；docs/23 §1.5 TC-DIAG 组）。
     *
     * 组合读取非敏感元数据：条目数 / 附件数 / 库创建时间 / 最后备份时间 /
     * 库 UUID 前缀。**字段集白名单**——结构上不含任何敏感数据（无标题 /
     * 无密码 / 无 secret，TC-DIAG-03）。只读允许面，无许可门禁
     * （6002/6003 不适用，与 `list_items` 同类）；锁定态 → 1001。
     */
    func diagnosticSummary() throws  -> FfiDiagnosticSummary
    
    /**
     * 关闭 Touch ID 解锁（docs/08 §4.1 disable，header 侧）。
     *
     * 门禁：需解锁态（1001）。原子重写 header → 禁用态；**幂等**——
     * 已是禁用态时不重写文件。Keychain 项删除在 Swift 侧先行且幂等；
     * 本方法失败非致命、可重试（docs/08 §8 降级矩阵）。
     */
    func disableBiometric() throws 
    
    /**
     * 库显示名（锁定时也可见）。
     */
    func displayName()  -> String
    
    /**
     * 启用 Touch ID 解锁（docs/08 §4.1 enable，header 侧）。
     *
     * 门禁：需解锁态（锁定 → 1001）。传入主密码而非 DEK（D-6）：内部
     * 经 `recover_dek` 重验证主密码并解出 DEK（错 → 1002，此时 header
     * 未变）→ K_bio 封装 DEK → 原子重写 header。
     *
     * `k_bio` 必须为 32 字节（否则 5002，建议经
     * [`CofferApp::new_biometric_unwrap_key`] 取得）。调用前 Swift 已把
     * k_bio 写入 Keychain（先 Keychain 后 header，docs/08 §4.1）；
     * 本方法返回 Err 时 header 保持原样，Swift 依据 Err 补偿删除
     * Keychain 项。
     */
    func enableBiometric(password: String, kBio: Data) throws 
    
    /**
     * CSV 明文导出（FR-8.3；锁定态 → 1001）。
     *
     * **明文导出的二次确认（FR-8.4）是调用方 UI 门禁**：Swift 侧必须先
     * 取得用户显式确认（UI 明示「导出文件为明文，包含全部密码」）才可
     * 调用本方法——内核不提供也不应绕过该门禁（D-11 默认关闭）。
     */
    func exportCsv(outPath: String) throws  -> FfiCsvExportResult
    
    /**
     * 1PUX 明文导出（FR-8.2，v0.7.0-T04；docs/23 TC-EXP 组；锁定态 → 1001）。
     *
     * 输出官方 1PUX v3 结构（ZIP + 明文 JSON + `files/` 附件），走
     * **ExportData 许可门禁组**（`write_guard(LicensedOp::ExportData)`，
     * 与 [`Self::export_csv`] 同落点；只读态 → 6002/6003，TC-EXP-09）。
     * **明文导出的二次确认（FR-8.4）是调用方 UI 门禁**：Swift 侧必须先
     * 取得用户显式确认（1PUX 为明文导出，含密码 / TOTP secret）才可调用
     * 本方法——内核不提供也不应绕过该门禁（纪律同 [`Self::export_csv`]）。
     *
     * # Errors
     *
     * `out_path` 为空串 → 5002 InvalidArgument（TC-EXP-15）；只读许可态 →
     * 6002/6003（TC-EXP-09）；锁定态 → 1001（TC-EXP-10）；目标父目录
     * 不存在 / ZIP 写入失败 → 2003（TC-EXP-11）；其余透传内核错误。
     */
    func exportOnePux(outPath: String) throws  -> FfiPuxExportResult
    
    /**
     * 生成密码短语（FR-3.3，EFF 词表不重复抽样；参数见
     * [`FfiPassphraseOptions`]）。镜像 [`VaultSession::generate_password`]
     * 的 Validation 映射：词数 3..=10、分隔符 1..=3 可打印字符，越界
     * → 码 1012。纯计算，无解锁门禁（与 `generate_password` 同语义）。
     */
    func generatePassphrase(opts: FfiPassphraseOptions) throws  -> String
    
    /**
     * 生成随机密码（CSPRNG，参数见 [`FfiPasswordGenOptions`]）。
     */
    func generatePassword(opts: FfiPasswordGenOptions) throws  -> String
    
    /**
     * 按需取字段明文值（密码等敏感值，随取随走，docs/07 §4.2）。
     * 条目不存在返回 Err(1011)（ItemNotFound）；条目存在但字段不存在
     * 返回 `None`（QA F-2：文档对齐实现，1011 语义保留）。
     */
    func getFieldValue(itemId: String, fieldId: String) throws  -> String?
    
    /**
     * 读取条目完整详情（Concealed 字段值掩码，docs/07 §4.2）。
     */
    func getItem(itemId: String) throws  -> FfiItemDetails?
    
    /**
     * 是否启用 Touch ID 封装（header `biometric_wrap.available`，
     * docs/08 D-1：语义 = 「用户意图开启」，锁定态可查）。纯读 header，
     * 无密钥操作；供 LockView 决定是否显示 Touch ID 按钮。实际可用性
     * 由 Swift 侧 Keychain 信号组合判定（docs/08 §8 降级矩阵）。
     */
    func hasBiometricWrap()  -> Bool
    
    /**
